class method1
{
    public int fun(int m) { return (m++ % 10); }
}
class Program
{
    static void Main(string[] args)
    {
        int a = 23, b = 0, c;
        method1 z = new method1();
        c = z.fun(++b * --a % 2); // b=1, a=22; 1*22%2=0. fun(0) returns 0.
        int d = z.fun(c-- + --a); // c becomes -1; a=21; fun(21) returns 1.
        Console.WriteLine(c);
        Console.WriteLine(a++);
        Console.WriteLine(d);
    }
}

